mapper.select:
SELECT i.*, w.node_name as warehouse_name, m.material_name, b.batch_no FROM spd_inventory i LEFT JOIN spd_org_node w ON i.warehouse_id = w.node_id AND w.del_flag = 0 LEFT JOIN spd_material m ON i.material_id = m.material_id AND m.del_flag = 0 LEFT JOIN spd_material_batch b ON i.batch_id = b.batch_id AND b.del_flag = 0
i.del_flag = 0
AND i.warehouse_id = #{queryForm.warehouseId}
AND i.material_id = #{queryForm.materialId}
AND i.batch_id = #{queryForm.batchId}
ORDER BY i.update_time DESC
